import { useState, type FormEvent } from 'react';
import {
  JxAlert,
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'правка задач' },
  { value: 'admin', label: 'Администратор', meta: 'полный доступ' },
];

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [sentTo, setSentTo] = useState<string | null>(null);

  const isValid = EMAIL_RE.test(email.trim());
  const errorText = touched && !isValid ? 'Укажите адрес вида name@company.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setSentTo(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{ display: 'grid', gap: '16px', maxWidth: '420px' }}
    >
      {sentTo && (
        <JxAlert intent="success" title="Приглашение отправлено">
          <span style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}>
            <span style={{ wordBreak: 'break-word' }}>Мы написали на {sentTo}.</span>
            <JxButton variant="ghost" size="sm" onClick={() => setSentTo(null)}>
              Закрыть
            </JxButton>
          </span>
        </JxAlert>
      )}

      <JxInputField
        label="Электронная почта"
        type="email"
        required
        autoComplete="email"
        placeholder="name@company.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        onBlur={() => setTouched(true)}
        helperText="Приглашение придёт на этот адрес и действует 7 дней"
        errorText={errorText}
      />

      <JxSelect
        label="Роль в команде"
        placeholder="Выберите роль"
        options={ROLES}
        value={role}
        onValueChange={setRole}
      />

      <JxSwitch
        label="Отправить уведомление на почту"
        checked={notify}
        onChange={(event) => setNotify(event.target.checked)}
      />

      <div style={{ display: 'flex', gap: '8px' }}>
        <JxButton type="submit" variant="primary" disabled={!isValid}>
          Отправить приглашение
        </JxButton>
      </div>
    </form>
  );
}

